var legacyFood = COMBO_DATA.bbq.items.concat(COMBO_DATA.mixed.items);
var foodSeen = {};
var foodItems = legacyFood.filter(function (item) {
  var key = (item.name + "|" + item.address).toLowerCase();
  if (foodSeen[key]) return false;
  foodSeen[key] = true;
  item.source = "Google Maps — địa điểm trong danh sách gốc; cần xác nhận hiện trạng";
  item.sourceUrl = "https://www.google.com/maps/search/?api=1&query=" + encodeURIComponent(item.name + " " + item.address + " Hà Nội");
  item.area = "Cầu Giấy";
  item.subcategory = /nướng|bbq|yakiniku/i.test(item.name + " " + item.desc) ? "Nướng & BBQ" : /lẩu/i.test(item.name + " " + item.desc) ? "Lẩu" : /sushi|nhật|japan/i.test(item.name + " " + item.desc) ? "Món Nhật" : /hàn|korean/i.test(item.name + " " + item.desc) ? "Món Hàn" : /phở|bún|mì|bánh|cơm/i.test(item.name + " " + item.desc) ? "Món Việt" : "Nhà hàng & món khác";
  item.priceMin = null;
  item.priceMax = null;
  return true;
});

